150	                // An earlier iteration already flagged this chain; stop walking up.
151	                if flags.contains_direct_eval() {
152	                    break;
153	                }
154	                flags.insert(ScopeFlags::DirectEval);
155	                ancestor = scoping.scope_parent_id(scope_id);
156	            }
157	        }
158	    }
