 Allocator::default();\n    let ret = minify(\n        &allocator,\n        &source_text,\n        source_type,\n        source_map_path,\n        mangle,\n        nospace,\n        max_iterations,\n    );\n    let printed = ret.code;\n    println!(\"{printed}\");\n\n    if let Some(map) = ret.map {\n        let visualizer = SourcemapVisualizer::new(&printed, &map);\n        println!(\"{}\", visualizer.get_url());\n        println!(\"{}\", visualizer.get_text());\n    }\n\n    if twice {\n        allocator.reset();\n        let printed2 = minify(&allocator, &printed, source_type, None, mangle, nospace, None).code;\n        println!(\"{printed2}\");\n        println!(\"same = {}\", printed == printed2);\n    }\n\n    Ok(())\n}\n\nfn minify(\n    allocator: &Allocator,\n    source_text: &str,\n    source_type: SourceType,\n    source_map_path: Option<PathBuf>,\n    mangle: bool,\n    nospace: bool,\n    max_iterations: Option<u8>,\n) -> CodegenReturn {\n    let ret = Parser::new(allocator, source_text, source_type).parse();\n    assert!(ret.errors.is_empty());\n    let mut program = ret.program;\n    let options = MinifierOptions {\n        mangle: mangle.then(MangleOptions::default),\n        compress: Some(CompressOptions { max_iterations, ..CompressOptions::smallest() }),\n    };\n    let ret = Minifier::new(options).minify(allocator, &mut program);\n    Codegen::new()\n        .with_options(CodegenOptions {\n            source_map_path,\n            minify: nospace,\n            comments: CommentOptions::disabled(),\n            ..CodegenOptions::default()\n        })\n        .with_scoping(ret.scoping)\n        .build(&program)\n}\n", "numLines": 111, "startLine": 1, "totalLines": 111}}

